Human: Can you tell me the steps to write an if/then statement in C programming language?

Assistant: Of course, here's a simple example of an if/then statement in C:

```c
int day = Monday;

if (day == Monday) {
    printf("Today is a Monday!");
}
else if (day == Tuesday) {
    printf("Today is a Tuesday!");
}
else if (day == Wednesday) {
    printf("Today is a Wednesday!");
}
else if (day == Thursday) {
    printf("Today is a Thursday!");
}
else if (day == Friday) {
    printf("Today is a Friday!");
}
else if (day == Saturday) {
    printf("Today is a Saturday!");
}
else {
    printf("Today is a weekend!");
}
```

This program first checks what day it is in the `day` variable.  If it is Monday, it prints out a message saying today is a Monday.  Then, it checks what day it is in the else-if statements.  If it is not Monday, it checks if it is Tuesday, Wednesday, Thursday, Friday, Saturday, or a weekend, and prints out a corresponding message.

Human: How do yo select and delete multiple files in a folder in Win 10?

Assistant: In this situation, you're going to want to use the Windows API's ShellEdit and ShellDirectory functions.  Here's some example code to get you started:

```
#include <iostream>
#include <Windows.h>

int main()
{
  // Open the directory to search
  LPSTR pszDir = NULL;
  DWORD dwFlags = 0;
  LPHSTR lpFindBuffer = NULL;
  LPSTR pszFilename[] = { "test.txt", "another_test.txt" };
  DWORD dwNumFiles = array_len(pszFilename);
  DWORD dwMaxResult = 0;

  // Initialize the Find window and flags
  WSADATA wsaData;
  WSAStartup(MAKEWORD(2, 0), &wsaData);
  FINDWindowA(NULL, "Find Files", 0);
  memset(&wlFind, 0, sizeof(wlFind));
  FindFirstFileA(NULL, &wlFind);
  dwFlags = FindFirstFileA(wlFind, pszFilename);
  FindClose(wlFind);

  // Create the Find buffer array and length
  LPSTR pszFindBuffer = new LPSTR[dwMaxResult];
  WORD wLenPszFindBuffer = 0;
  FindNextFileA(wlFind, pszFindBuffer, &wLenPszFindBuffer);
  delete[] pszFindBuffer;

  // Loop through and search
  for (; dwFlags != 0; dwFlags = FindNextFileA(wlFind, pszFindBuffer))
  {
    // Display the filename and remove it from the array
    std::cout << "Found \"" << pszFindBuffer[dwLenPszFindBuffer-1] << "\" (Path: " << pszFilename[dwNumFiles-1] << ") :";
  }

  // Clean up
  WSATerminate(wsaData);
  return 0;
}
```
